"""Gabarit de La Brève (deux pages A4). Exécuter : python3 la-breve-kit.py
Recrée build.py, engine.js, sun.svg, make_pdf.py et edition-exemple.json dans le dossier courant."""
import base64, hashlib
FICHIERS = {
    'build.py': '',
    'engine.js': '',
    'sun.svg': '',
    'make_pdf.py': '',
    'edition-exemple.json': '',
}
for nom, contenu in FICHIERS.items():
    data = base64.b64decode(contenu)
    open(nom, "wb").write(data)
    print("extrait :", nom, len(data), "octets")
